if (window.PRODUTOS && Array.isArray(window.PRODUTOS_CHUTEIRAS_EXTRA)) {
  let proximoIdChuteiras = Math.max(0, ...PRODUTOS.map(produto => produto.id)) + 1;
  PRODUTOS_CHUTEIRAS_EXTRA.forEach(produto => {
    produto.id = proximoIdChuteiras++;
    produto.preco = 199;
    produto.marca = /Nike/i.test(produto.nome) ? 'Nike'
      : /adidas|F50/i.test(produto.nome) ? 'Adidas'
      : /Puma/i.test(produto.nome) ? 'Puma'
      : /New Balance/i.test(produto.nome) ? 'New Balance'
      : 'Catálogo Futebol';
    produto.caracteristicas = ['Galeria completa', 'Chuteira de futebol', produto.linha];
  });
  PRODUTOS.push(...PRODUTOS_CHUTEIRAS_EXTRA);
}